func CtyToPolicyValue(raw cty.Value) PolicyValue {
	raw, pvms := raw.UnmarkDeepWithPaths()
	redactedPaths, _ := marks.PathsWithMark(pvms, marks.Sensitive)
	return PolicyValue{
		Raw:           raw,
		RedactedPaths: redactedPaths,
	}
}
